      // caches are per-addr, so we just clear the well-known ones.
      try { if (window._wCachedPoolInfo) delete window._wCachedPoolInfo; } catch(_){}
      try { if (window._wStakePerDayByAddr) window._wStakePerDayByAddr = {}; } catch(_){}
